    def first_digit_is_odd(n):
        while n >= 10:
            n //= 10
        return n % 2 == 1

    def last_digit_is_odd(n):
        return n % 10 % 2 == 1

    count = 0
    for num in nums:
        if num > 10 and first_digit_is_odd(num) and last_digit_is_odd(num):
            count += 1
    return count

